window.AUTH=window.AUTH||{};window.AUTH["08-1119"]={"d":"08-1119","id":"2009/08-1119","n":"Milavetz, Gallop & Milavetz, P.A. v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/202236/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/08-1225-milavetz-v-united-statesunited-states-v-milavetz-brief-merits","n":160}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep559/usrep559229/usrep559229.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"128 S. Ct. 831","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Anderson v. Dunn","cite":"19 U.S. 204","y":1821,"id":"1789-1850/19us204","sc":1,"sum":"Though the contempt power will not be found in the Constitution in plain terms, necessity compels it. The power is inherent in the structure and purpose of Congress. The absence of such power would lead to a total loss of power, exposing the Congress \"to every indignity.\".","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Attorney Grievance Comm’n v. Culver","cite":"849 A.2d 423","y":2004,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/849/423/","by":{"0":"33, 50, 52"}},{"t":"case","label":"Bates v. State Bar","cite":"433 U.S. 350","y":1977,"id":"1976/76-316","sc":1,"sum":"The Court found that the rule violated the First and Fourteenth Amendments. Justice Blackmun argued that commercial speech does merit First Amendment protection given the important functions it serves in society, such as providing consumers with information about services and products, and helping to allocate resources in the American system of free-enterprise.","sumSrc":"Oyez","by":{"0":"55, 56, 57"}},{"t":"case","label":"BFP v. RTC","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"0":"43, 44, 45"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"sum":"The Court held that a Ku Klux Klan's First Amendment rights were violated by an Ohio criminal syndicalism law.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Burgess v. United States","cite":"128 S. Ct. 1572","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Caperton v. A.T. Massey Coal Co.","cite":"129 S. Ct. 2252","y":2009,"id":"2008/08-22","sc":1,"sum":"The Court held that the Due Process Clause of the 14th Amendment required that a justice recuse himself from a case if one of the parties in the suit donated $3 million to the justice's election campaign.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Central Hudson Gas & Elec. Corp. v. Public Serv. Comm’n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"op":5,"ar":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":"59"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Cohen v. Hurley","cite":"366 U.S. 117","y":1961,"id":"1960/84","sc":1,"sum":"Such disciplinary action did not violate petitioner's rights under the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Conrad, Rubin & Lesser v. Pender","cite":"289 U.S. 472","y":1933,"id":"scdb/1932-056","sc":1,"op":4,"by":{"0":"32"}},{"t":"case","label":"Davis v. Michigan Dep’t of the Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Edenfield v. Fane","cite":"507 U.S. 761","y":1993,"id":"1992/91-1594","sc":1,"sum":"As applied to CPA solicitation in the business context, Florida's prohibition is inconsistent with the free speech guarantees of the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"56"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44, 45"}},{"t":"case","label":"FTC v. Colgate-Palmolive Co.","cite":"380 U.S. 374","y":1965,"id":"1964/62","sc":1,"op":1,"sum":"The Federal Trade Commission charged respondents, an advertiser and an advertising agency, with using commercials that were deceptive within the meaning of § 5 of the Federal Trade Commission Act. The commercials purported to give viewers visual proof that the advertiser's shaving cream could soften \"sandpaper,\" but unknown to viewers the substance that appeared to be sandpaper in the commercials was in fact a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"62"}},{"t":"case","label":"Fidgeon v. Sharpe","cite":"5 Taunt. 539","y":1814,"court":"C.P.","url":"https://www.courtlistener.com/c/Taunt./5/539/","by":{"0":"31"}},{"t":"case","label":"Florida Bar v. Went For It, Inc.","cite":"515 U.S. 618","y":1995,"id":"1994/94-226","sc":1,"sum":"Lawyer advertising is commercial speech and as such, is accorded only a limited measure of First Amendment protection.","sumSrc":"Oyez","by":{"0":"55, 60, 67"}},{"t":"case","label":"Gentile v. State Bar","cite":"501 U.S. 1030","y":1991,"id":"1990/89-1836","sc":1,"sum":"The judgment is reversed. 106 Nev. 60, 787 P. 2d 386, reversed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts III and VI, concluding that, as interpreted by the Nevada Supreme Court, Rule 177 is void for vagueness. Its safe harbor provision, Rule 177(3), misled Gentile into thinking that he could give his press conference without fear of discipline. Given the Rule's grammatical structure …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Goldfarb v. Virginia State Bar","cite":"421 U.S. 773","y":1975,"id":"1974/74-70","sc":1,"sum":"The minimumfee schedule, as published by the County Bar Association and enforced by the State Bar, violates § 1 of the Sherman Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Grievance Adm’r v. Fried","cite":"570 N.W.2d 262","y":1997,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/570/262/","by":{"0":"53"}},{"t":"case","label":"HUD v. Rucker","cite":"535 U.S. 125","y":2002,"id":"2001/00-1770","sc":1,"sum":"The Court held that the Anti-Drug Abuse Act of 1988 unambiguously requires lease terms that vest local public housing authorities with the discretion to evict tenants for the drug-related activity of household members and guests whether or not the tenant knew, or should have known, about the activity.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Hawaii v. Office of Hawaiian Affairs","cite":"129 S. Ct. 1436","y":2009,"id":"2008/07-1372","sc":1,"sum":"The Court held that the Apology Resolution did not restrict Hawaii's sovereign authority to transfer publicly held land for private development.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Heintz v. Jenkins","cite":"514 U.S. 291","y":1995,"id":"1994/94-367","sc":1,"op":1,"ar":1,"sum":"Holding that “debt collector” as used in the Fair Debt Collection Practices Act, 15 U. S. C. § 1692a(6), includes attorneys notwithstand­ ing the deﬁnition’s lack of an express reference to lawyers or litigation.","sumSrc":"opinion","by":{"0":"19"}},{"t":"case","label":"Hersh v. United States ex rel. Mukasey","cite":"553 F.3d 743","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/743/","op":4,"sum":"Noting that “the government has a compelling interest in ensuring that those who enter bankruptcy know what it entails”.","sumSrc":"brief:0","by":{"0":"passim"}},{"t":"case","label":"Ibanez v. Florida Dep’t of Bus. & Prof’l Regulation","cite":"512 U.S. 136","y":1994,"id":"1993/93-639","sc":1,"op":1,"sum":"The Court held that Ibanez's use of her CPA and CFP designations constituted commercial speech, which can only be restricted if it can be proven to be false or misleading and the state has a substantial interest in restricting it. Because Ibanez is fully licensed, her use of the designations was neither false nor misleading.","sumSrc":"Oyez","by":{"0":"66"}},{"t":"case","label":"Jones v. Bank of Santa Fe (In re Courtesy Inns, Ltd.)","cite":"40 F.3d 1084","y":1994,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/40/1084/","by":{"0":"48"}},{"t":"case","label":"Kawaauhau v. Geiger","cite":"523 U.S. 57","y":1998,"id":"1997/97-115","sc":1,"sum":"The Court held that \"debts arising from recklessly or negligently inflicted injuries do not fall within the compass of [section 523(a)(6)].\" Therefore, the debt is dischargeable.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Kimel v. Florida Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Lawson v. Suwannee Fruit & S.S. Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"sum":"Under § 8 (f) (1) of the Act, the employer was liable only for permanent partial disability (loss of the left eye), and the remainder of the compensation due for permanent total disability was payable out of the special fund established by § 44 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Legal Servs. Corp. v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"sum":"The Court held that the funding provision that limited arguments legal services attorneys were allowed to make on behalf of indigent welfare claimants violated the First Amendment by regulating private speech and insulating federal law from legitimate judicial challenge.","sumSrc":"Oyez","by":{"0":"49, 50"}},{"t":"case","label":"Marrama v. Citizens Bank","cite":"549 U.S. 365","y":2007,"id":"2006/05-996","sc":1,"sum":"The Court ruled that there is a \"bad faith\" exception to the right of conversion in Section 706(a). The opinion by Justice John Paul Stevens held that although the vast majority of Chapter 7 debtors can convert to Chapter 13, a Chapter 7 debtor who engages in bad faith conduct does not qualify as a \"debtor\" under Chapter 13 and thus cannot convert his petition.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"McCuin v. Texas Power & Light Co.","cite":"714 F.2d 1255","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/714/1255/","by":{"0":"53"}},{"t":"case","label":"Members of the City Council v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"op":2,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Morgan v. Brundrett, 5 Barn. & Ad. 289","cite":"110 Eng. Rep. 798","y":1833,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./110/798/","op":1,"by":{"0":"31"}},{"t":"case","label":"NLRB v. Town & Country Elec., Inc.","cite":"516 U.S. 85","y":1995,"id":"1995/94-947","sc":1,"sum":"The Supreme Court ruled for the Board and held that individuals can meet the definition of employee even if they are paid by a union to organize a non-union company while on company payroll.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Northern Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Ohralik v. Ohio State Bar Ass’n","cite":"436 U.S. 447","y":1978,"id":"1977/76-1650","sc":1,"sum":"The Court held that a state may constitutionally discipline a lawyer for soliciting clients in person and for financial gain under circumstances likely to pose dangers that the state has a right to prevent.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Olsen v. Gonzales","cite":"350 B.R. 906","y":2006,"court":"D. Or.","url":"https://www.courtlistener.com/c/B.R./350/906/","by":{"0":"60"}},{"t":"case","label":"Paulding v. Chrome Steel Co.","cite":"94 N.Y. 334","y":1894,"url":"https://www.courtlistener.com/c/N.Y./94/334/","sum":"Interpreting state law that voided transfers “in contemplation of the insolvency of [the] company”.","sumSrc":"brief:0","by":{"0":"31"}},{"t":"case","label":"Pittsburgh Press Co. v. Pittsburgh Comm’n on Hu- man Relations","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Price v. Lehtinen (In re Lehtinen)","cite":"564 F.3d 1052","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/564/1052/","by":{"0":"48"}},{"t":"case","label":"Price v. United States Tr. (In re Price)","cite":"353 F.3d 1135","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/353/1135/","by":{"0":"34, 46"}},{"t":"case","label":"Riley v. National Fed’n of the Blind of N.C., Inc.","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"op":2,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"59"}},{"t":"case","label":"Rittenhouse v. Delta Home Improvement, Inc. (In re Desilets)","cite":"291 F.3d 925","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/291/925/","by":{"0":"41"}},{"t":"case","label":"Roadway Express, Inc. v. Piper","cite":"447 U.S. 752","y":1980,"id":"1979/79-701","sc":1,"sum":"Respondents were counsel for the plaintiffs in a civil rights class action in Federal District Court against petitioner alleging that its employment policies discriminated on the basis of race. Because respondents failed to comply with orders relating to discovery and the filing of briefs, petitioner moved to dismiss the suit and requested an award of attorney's fees and court costs under Federal Rule of Civil …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 52"}},{"t":"case","label":"Rubin v. Coors Brewing Co.","cite":"514 U.S. 476","y":1995,"id":"1994/93-1631","sc":1,"sum":"a case in which the Court held that for the government to regulate commercial speech, the government must have a substantial interest that the regulation directly affects.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Sperry v. Florida ex rel. Florida Bar","cite":"373 U.S. 379","y":1963,"id":"1962/322","sc":1,"sum":"Petitioner is not a lawyer and has never been admitted to the Bar of any State; but, under regulations issued by the Commissioner of Patents with the approval of the Secretary of Commerce pursuant to 35 U. S. C. § 31, he has been authorized to practice before the United States Patent Office. As part of that practice, he has for many years represented patent applicants, prepared and prosecuted their applications, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Edge Broad. Co.","cite":"509 U.S. 418","y":1993,"id":"1992/92-486","sc":1,"sum":"The judgment is reversed. 956 F. 2d 263, reversed. JUSTICE WHITE delivered the opinion of the Court as to all but Part III-D, concluding that the statutes regulate commercial speech in a manner that does not violate the First Amendment. Pp. 426-435, 436.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"United States v. Williams","cite":"128 S. Ct. 1830","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"28, 51, 54"}},{"t":"case","label":"Virginia State Bd. of Pharmacy v. Virginia Citizens Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"op":1,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"0":"55, 56"}},{"t":"case","label":"West Virginia State Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"0":"59"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"0":"58"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Zauderer v. Office of Disciplinary Counsel of the Supreme Court","cite":"471 U.S. 626","y":1985,"id":"1984/83-2166","sc":1,"op":19,"sum":"The reprimand is sustainable to the extent that it is based on appellant's advertisement involving his terms of representation in drunken driving cases and on the omission of information regarding his contingent-fee arrangements in his Dalkon Shield advertisement. But insofar as the reprimand is based on appellant's use of an illustration in his advertisement and his offer of legal advice, the reprimand violated his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"48"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"70"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","subs":["(b)","(b)(1)","(b)(2000)","(b)(2)","(b)(2)(A)(i)","(b)(2)(A)(iii)","(b)(3)","(b)(4)(B)","(b)(4)(C)","(b)(4)(C)(ii)(I)","(b)(4)(C)(ii)(II)","(b)(4)(D)","(b)(6)"],"stext":{"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","paras":[[0,"(a) The court may dismiss a case under this chapter only after notice and a hearing and only for cause, including—"],[1,"(1) unreasonable delay by the debtor that is prejudicial to creditors;"],[1,"(2) nonpayment of any fees or charges required under chapter 123 of title 28; and"],[1,"(3) failure of the debtor in a voluntary case to file, within fifteen days or such additional time as the court may allow after the filing of the petition commencing such case, the information required by paragraph (1) of section 521(a), but only on a motion by the United States trustee."],[0,"(b)(1) After notice and a hearing, the court, on its own motion or on a motion by the United States trustee, trustee (or bankruptcy administrator, if any), or any party in interest, may dismiss a case filed by an individual debtor under this chapter whose debts are primarily consumer debts, or, with the debtor's consent, convert such a case to a case under chapter 11 or 13 of this title, if it finds that the granting of relief would be an abuse of the provisions of this chapter. In making a determination whether to dismiss a case under this section, the court may not take into consideration whether a debtor has made, or continues to make, charitable contributions (that meet the definition of \"charitable contribution\" under section 548(d)(3)) to any qualified religious or charitable entity or organization (as that term is defined in section 548(d)(4))."],[0,"(2)(A)(i) In considering under paragraph (1) whether the granting of relief would be an abuse of the provisions of this chapter, the court shall presume abuse exists if the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv), and multiplied by 60 is not less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims in the case, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(ii)(I) The debtor's monthly expenses shall be the debtor's applicable monthly expense amounts specified under the National Standards and Local Standards, and the debtor's actual monthly expenses for the categories specified as Other Necessary Expenses issued by the Internal Revenue Service for the area in which the debtor resides, as in effect on the date of the order for relief, for the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case, if the spouse is not otherwise a dependent. Such expenses shall include reasonably necessary health insurance, disability insurance, and health savings account expenses for the debtor, the spouse of the debtor, or the dependents of the debtor. Notwithstanding any other provision of this clause, the monthly expenses of the debtor shall not include any payments for debts. In addition, the debtor's monthly expenses shall include the debtor's reasonably necessary expenses incurred to maintain the safety of the debtor and the family of the debtor from family violence as identified under section 302 of the Family Violence Prevention and Services Act, or other applicable Federal law. The expenses included in the debtor's monthly expenses described in the preceding sentence shall be kept confidential by the court. In addition, if it is demonstrated that it is reasonable and necessary, the debtor's monthly expenses may also include an additional allowance for food and clothing of up to 5 percent of the food and clothing categories as specified by the National Standards issued by the Internal Revenue Service."],[0,"(II) In addition, the debtor's monthly expenses may include, if applicable, the continuation of actual expenses paid by the debtor that are reasonable and necessary for care and support of an elderly, chronically ill, or disabled household member or member of the debtor's immediate family (including parents, grandparents, siblings, children, and grandchildren of the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case who is not a dependent) and who is unable to pay for such reasonable and necessary expenses. Such monthly expenses may include, if applicable, contributions to an account of a qualified ABLE program to the extent such contributions are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986) and if the designated beneficiary of such account is a child, stepchild, grandchild, or stepgrandchild of the debtor."],[0,"(III) In addition, for a debtor eligible for chapter 13, the debtor's monthly expenses may include the actual administrative expenses of administering a chapter 13 plan for the district in which the debtor resides, up to an amount of 10 percent of the projected plan payments, as determined under schedules issued by the Executive Office for United States Trustees."],[0,"(IV) In addition, the debtor's monthly expenses may include the actual expenses for each dependent child less than 18 years of age, not to exceed $1,500 1 per year per child, to attend a private or public elementary or secondary school if the debtor provides documentation of such expenses and a detailed explanation of why such expenses are reasonable and necessary, and why such expenses are not already accounted for in the National Standards, Local Standards, or Other Necessary Expenses referred to in subclause (I)."],[0,"(V) In addition, the debtor's monthly expenses may include an allowance for housing and utilities, in excess of the allowance specified by the Local Standards for housing and utilities issued by the Internal Revenue Service, based on the actual expenses for home energy costs if the debtor provides documentation of such actual expenses and demonstrates that such actual expenses are reasonable and necessary."],[0,"(iii) The debtor's average monthly payments on account of secured debts shall be calculated as the sum of—"],[1,"(I) the total of all amounts scheduled as contractually due to secured creditors in each month of the 60 months following the date of the filing of the petition; and"],[1,"(II) any additional payments to secured creditors necessary for the debtor, in filing a plan under chapter 13 of this title, to maintain possession of the debtor's primary residence, motor vehicle, or other property necessary for the support of the debtor and the debtor's dependents, that serves as collateral for secured debts;"],[0,"divided by 60."],[0,"(iv) The debtor's expenses for payment of all priority claims (including priority child support and alimony claims) shall be calculated as the total amount of debts entitled to priority, divided by 60."],[0,"(B)(i) In any proceeding brought under this subsection, the presumption of abuse may only be rebutted by demonstrating special circumstances, such as a serious medical condition or a call or order to active duty in the Armed Forces, to the extent such special circumstances that justify additional expenses or adjustments of current monthly income for which there is no reasonable alternative."],[0,"(ii) In order to establish special circumstances, the debtor shall be required to itemize each additional expense or adjustment of income and to provide—"],[1,"(I) documentation for such expense or adjustment to income; and"],[1,"(II) a detailed explanation of the special circumstances that make such expenses or adjustment to income necessary and reasonable."],[0,"(iii) The debtor shall attest under oath to the accuracy of any information provided to demonstrate that additional expenses or adjustments to income are required."],[0,"(iv) The presumption of abuse may only be rebutted if the additional expenses or adjustments to income referred to in clause (i) cause the product of the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv) of subparagraph (A) when multiplied by 60 to be less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(C) As part of the schedule of current income and expenditures required under section 521, the debtor shall include a statement of the debtor's current monthly income, and the calculations that determine whether a presumption arises under subparagraph (A)(i), that show how each such amount is calculated."],[0,"(D) Subparagraphs (A) through (C) shall not apply, and the court may not dismiss or convert a case based on any form of means testing—"],[1,"(i) if the debtor is a disabled veteran (as defined in section 3741(1) of title 38), and the indebtedness occurred primarily during a period during which he or she was—"],[2,"(I) on active duty (as defined in section 101(d)(1) of title 10); or"],[2,"(II) performing a homeland defense activity (as defined in section 901(1) of title 32); or"],[1,"(ii) with respect to the debtor, while the debtor is—"],[2,"(I) on, and during the 540-day period beginning immediately after the debtor is released from, a period of active duty (as defined in section 101(d)(1) of title 10) of not less than 90 days; or"],[2,"(II) performing, and during the 540-day period beginning immediately after the debtor is no longer performing, a homeland defense activity (as defined in section 901(1) of title 32) performed for a period of not less than 90 days;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/707?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","tname":"Bankruptcy","by":{"0":"35, 35, 35, 38, 34, 35, 11, 35, 36, 45, 40, 36, 36, 36, 40, 46, 38, 38, 38, 45, 38, 35"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(2)(C)","(a)(2)(A)(2000)","(a)(2)(C)(2000)","(a)(2)(C)(1988)"],"by":{"0":"35, 35, 35, 35, 34"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(3)","(4A)","(12A)","(12A)(A)","(12A)(B)","(12A)(C)","(12A)(D)","(12A)(E)","(41)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"4, 22, 4, 22, 4, 22, 4, 12, 17, 18, 25, 64, 4, 11, 17, 18, 64, 19, 20, 4, 19, 19, 20, 19, 19, 17"}},{"t":"usc","label":"11 U.S.C. § 104","url":"https://www.law.cornell.edu/uscode/text/11/104","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"by":{"0":"24, 49"}},{"t":"usc","label":"11 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/11/109","subs":["(b)","(e)"],"by":{"0":"36, 36"}},{"t":"usc","label":"11 U.S.C. § 110","url":"https://www.law.cornell.edu/uscode/text/11/110","subs":["(a)","(a)(1)","(b)","(c)","(d)","(e)","(e)(2)(A)","(f)","(g)","(h)","(i)","(k)","(j)"],"by":{"0":"18, 18, 4, 4, 4, 4, 18, 4, 4, 4, 53, 18, 53, 18, 53, 18, 53"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"0":"24"}},{"t":"usc","label":"11 U.S.C. § 329","url":"https://www.law.cornell.edu/uscode/text/11/329","stext":{"head":"§329. Debtor's transactions with attorneys","paras":[[0,"(a) Any attorney representing a debtor in a case under this title, or in connection with such a case, whether or not such attorney applies for compensation under this title, shall file with the court a statement of the compensation paid or agreed to be paid, if such payment or agreement was made after one year before the date of the filing of the petition, for services rendered or to be rendered in contemplation of or in connection with the case by such attorney, and the source of such compensation."],[0,"(b) If such compensation exceeds the reasonable value of any such services, the court may cancel any such agreement, or order the return of any such payment, to the extent excessive, to—"],[1,"(1) the estate, if the property transferred—"],[2,"(A) would have been property of the estate; or"],[2,"(B) was to be paid by or on behalf of the debtor under a plan under chapter 11, 12, or 13 of this title; or"],[1,"(2) the entity that made such payment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/329?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§329. Debtor's transactions with attorneys","tname":"Bankruptcy","by":{"0":"24"}},{"t":"usc","label":"11 U.S.C. § 342","url":"https://www.law.cornell.edu/uscode/text/11/342","subs":["(b)(1)"],"by":{"0":"23"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"0":"22"}},{"t":"usc","label":"11 U.S.C. § 522","url":"https://www.law.cornell.edu/uscode/text/11/522","subs":["(b)"],"by":{"0":"22"}},{"t":"usc","label":"11 U.S.C. § 526","url":"https://www.law.cornell.edu/uscode/text/11/526","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(4)","(c)","(c)(2)","(c)(2)(A)","(c)(2)(B)","(c)(3)","(c)(3)(A)","(c)(5)","(c)(5)(A)","(d)(1)","(d)(2)(A)"],"stext":{"head":"§526. Restrictions on debt relief agencies","paras":[[0,"(a) A debt relief agency shall not—"],[1,"(1) fail to perform any service that such agency informed an assisted person or prospective assisted person it would provide in connection with a case or proceeding under this title;"],[1,"(2) make any statement, or counsel or advise any assisted person or prospective assisted person to make a statement in a document filed in a case or proceeding under this title, that is untrue or misleading, or that upon the exercise of reasonable care, should have been known by such agency to be untrue or misleading;"],[1,"(3) misrepresent to any assisted person or prospective assisted person, directly or indirectly, affirmatively or by material omission, with respect to—"],[2,"(A) the services that such agency will provide to such person; or"],[2,"(B) the benefits and risks that may result if such person becomes a debtor in a case under this title; or"],[1,"(4) advise an assisted person or prospective assisted person to incur more debt in contemplation of such person filing a case under this title or to pay an attorney or bankruptcy petition preparer a fee or charge for services performed as part of preparing for or representing a debtor in a case under this title."],[0,"(b) Any waiver by any assisted person of any protection or right provided under this section shall not be enforceable against the debtor by any Federal or State court or any other person, but may be enforced against a debt relief agency."],[0,"(c)(1) Any contract for bankruptcy assistance between a debt relief agency and an assisted person that does not comply with the material requirements of this section, section 527, or section 528 shall be void and may not be enforced by any Federal or State court or by any other person, other than such assisted person."],[0,"(2) Any debt relief agency shall be liable to an assisted person in the amount of any fees or charges in connection with providing bankruptcy assistance to such person that such debt relief agency has received, for actual damages, and for reasonable attorneys' fees and costs if such agency is found, after notice and a hearing, to have—"],[1,"(A) intentionally or negligently failed to comply with any provision of this section, section 527, or section 528 with respect to a case or proceeding under this title for such assisted person;"],[1,"(B) provided bankruptcy assistance to an assisted person in a case or proceeding under this title that is dismissed or converted to a case under another chapter of this title because of such agency's intentional or negligent failure to file any required document including those specified in section 521; or"],[1,"(C) intentionally or negligently disregarded the material requirements of this title or the Federal Rules of Bankruptcy Procedure applicable to such agency."],[0,"(3) In addition to such other remedies as are provided under State law, whenever the chief law enforcement officer of a State, or an official or agency designated by a State, has reason to believe that any person has violated or is violating this section, the State—"],[1,"(A) may bring an action to enjoin such violation;"],[1,"(B) may bring an action on behalf of its residents to recover the actual damages of assisted persons arising from such violation, including any liability under paragraph (2); and"],[1,"(C) in the case of any successful action under subparagraph (A) or (B), shall be awarded the costs of the action and reasonable attorneys' fees as determined by the court."],[0,"(4) The district courts of the United States for districts located in the State shall have concurrent jurisdiction of any action under subparagraph (A) or (B) of paragraph (3)."],[0,"(5) Notwithstanding any other provision of Federal law and in addition to any other remedy provided under Federal or State law, if the court, on its own motion or on the motion of the United States trustee or the debtor, finds that a person intentionally violated this section, or engaged in a clear and consistent pattern or practice of violating this section, the court may—"],[1,"(A) enjoin the violation of such section; or"],[1,"(B) impose an appropriate civil penalty against such person."],[0,"(d) No provision of this section, section 527, or section 528 shall—"],[1,"(1) annul, alter, affect, or exempt any person subject to such sections from complying with any law of any State except to the extent that such law is inconsistent with those sections, and then only to the extent of the inconsistency; or"],[1,"(2) be deemed to limit or curtail the authority or ability—"],[2,"(A) of a State or subdivision or instrumentality thereof, to determine and enforce qualifications for the practice of law under the laws of that State; or"],[2,"(B) of a Federal court to determine and enforce the qualifications for the practice of law before that court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/526?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":2,"head":"§526. Restrictions on debt relief agencies","tname":"Bankruptcy","by":{"0":"39, 39, 5, 27, 39, 5, 39, 5, 39, passim, 39, 6, 41, 46, 40, 39, 6, 40, 41, 6, 41, 24, 25"}},{"t":"usc","label":"11 U.S.C. § 527","url":"https://www.law.cornell.edu/uscode/text/11/527","subs":["(a)(1)","(a)(2)","(b)"],"stext":{"head":"§527. Disclosures","paras":[[0,"(a) A debt relief agency providing bankruptcy assistance to an assisted person shall provide—"],[1,"(1) the written notice required under section 342(b)(1); and"],[1,"(2) to the extent not covered in the written notice described in paragraph (1), and not later than 3 business days after the first date on which a debt relief agency first offers to provide any bankruptcy assistance services to an assisted person, a clear and conspicuous written notice advising assisted persons that—"],[2,"(A) all information that the assisted person is required to provide with a petition and thereafter during a case under this title is required to be complete, accurate, and truthful;"],[2,"(B) all assets and all liabilities are required to be completely and accurately disclosed in the documents filed to commence the case, and the replacement value of each asset as defined in section 506 must be stated in those documents where requested after reasonable inquiry to establish such value;"],[2,"(C) current monthly income, the amounts specified in section 707(b)(2), and, in a case under chapter 13 of this title, disposable income (determined in accordance with section 707(b)(2)), are required to be stated after reasonable inquiry; and"],[2,"(D) information that an assisted person provides during their case may be audited pursuant to this title, and that failure to provide such information may result in dismissal of the case under this title or other sanction, including a criminal sanction."],[0,"(b) A debt relief agency providing bankruptcy assistance to an assisted person shall provide each assisted person at the same time as the notices required under subsection (a)(1) the following statement, to the extent applicable, or one substantially similar. The statement shall be clear and conspicuous and shall be in a single document separate from other documents or notices provided to the assisted person:"],[0,"\"IMPORTANT INFORMATION ABOUT BANKRUPTCY ASSISTANCE SERVICES FROM AN ATTORNEY OR BANKRUPTCY PETITION PREPARER."],[0,"\"If you decide to seek bankruptcy relief, you can represent yourself, you can hire an attorney to represent you, or you can get help in some localities from a bankruptcy petition preparer who is not an attorney. THE LAW REQUIRES AN ATTORNEY OR BANKRUPTCY PETITION PREPARER TO GIVE YOU A WRITTEN CONTRACT SPECIFYING WHAT THE ATTORNEY OR BANKRUPTCY PETITION PREPARER WILL DO FOR YOU AND HOW MUCH IT WILL COST. Ask to see the contract before you hire anyone."],[0,"\"The following information helps you understand what must be done in a routine bankruptcy case to help you evaluate how much service you need. Although bankruptcy can be complex, many cases are routine."],[0,"\"Before filing a bankruptcy case, either you or your attorney should analyze your eligibility for different forms of debt relief available under the Bankruptcy Code and which form of relief is most likely to be beneficial for you. Be sure you understand the relief you can obtain and its limitations. To file a bankruptcy case, documents called a Petition, Schedules, and Statement of Financial Affairs, and in some cases a Statement of Intention, need to be prepared correctly and filed with the bankruptcy court. You will have to pay a filing fee to the bankruptcy court. Once your case starts, you will have to attend the required first meeting of creditors where you may be questioned by a court official called a 'trustee' and by creditors."],[0,"\"If you choose to file a chapter 7 case, you may be asked by a creditor to reaffirm a debt. You may want help deciding whether to do so. A creditor is not permitted to coerce you into reaffirming your debts."],[0,"\"If you choose to file a chapter 13 case in which you repay your creditors what you can afford over 3 to 5 years, you may also want help with preparing your chapter 13 plan and with the confirmation hearing on your plan which will be before a bankruptcy judge."],[0,"\"If you select another type of relief under the Bankruptcy Code other than chapter 7 or chapter 13, you will want to find out what should be done from someone familiar with that type of relief."],[0,"\"Your bankruptcy case may also involve litigation. You are generally permitted to represent yourself in litigation in bankruptcy court, but only attorneys, not bankruptcy petition preparers, can give you legal advice.\"."],[0,"(c) Except to the extent the debt relief agency provides the required information itself after reasonably diligent inquiry of the assisted person or others so as to obtain such information reasonably accurately for inclusion on the petition, schedules or statement of financial affairs, a debt relief agency providing bankruptcy assistance to an assisted person, to the extent permitted by nonbankruptcy law, shall provide each assisted person at the time required for the notice required under subsection (a)(1) reasonably sufficient information (which shall be provided in a clear and conspicuous writing) to the assisted person on how to provide all the information the assisted person is required to provide under this title pursuant to section 521, including—"],[1,"(1) how to value assets at replacement value, determine current monthly income, the amounts specified in section 707(b)(2) and, in a chapter 13 case, how to determine disposable income in accordance with section 707(b)(2) and related calculations;"],[1,"(2) how to complete the list of creditors, including how to determine what amount is owed and what address for the creditor should be shown; and"],[1,"(3) how to determine what property is exempt and how to value exempt property at replacement value as defined in section 506."],[0,"(d) A debt relief agency shall maintain a copy of the notices required under subsection (a) of this section for 2 years after the date on which the notice is given the assisted person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/527?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§527. Disclosures","tname":"Bankruptcy","by":{"0":"4, 23, 23, 27, 23"}},{"t":"usc","label":"11 U.S.C. § 528","url":"https://www.law.cornell.edu/uscode/text/11/528","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(4)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(B)"],"stext":{"head":"§528. Requirements for debt relief agencies","paras":[[0,"(a) A debt relief agency shall—"],[1,"(1) not later than 5 business days after the first date on which such agency provides any bankruptcy assistance services to an assisted person, but prior to such assisted person's petition under this title being filed, execute a written contract with such assisted person that explains clearly and conspicuously—"],[2,"(A) the services such agency will provide to such assisted person; and"],[2,"(B) the fees or charges for such services, and the terms of payment;"],[1,"(2) provide the assisted person with a copy of the fully executed and completed contract;"],[1,"(3) clearly and conspicuously disclose in any advertisement of bankruptcy assistance services or of the benefits of bankruptcy directed to the general public (whether in general media, seminars or specific mailings, telephonic or electronic messages, or otherwise) that the services or benefits are with respect to bankruptcy relief under this title; and"],[1,"(4) clearly and conspicuously use the following statement in such advertisement: \"We are a debt relief agency. We help people file for bankruptcy relief under the Bankruptcy Code.\" or a substantially similar statement."],[0,"(b)(1) An advertisement of bankruptcy assistance services or of the benefits of bankruptcy directed to the general public includes—"],[1,"(A) descriptions of bankruptcy assistance in connection with a chapter 13 plan whether or not chapter 13 is specifically mentioned in such advertisement; and"],[1,"(B) statements such as \"federally supervised repayment plan\" or \"Federal debt restructuring help\" or other similar statements that could lead a reasonable consumer to believe that debt counseling was being offered when in fact the services were directed to providing bankruptcy assistance with a chapter 13 plan or other form of bankruptcy relief under this title."],[0,"(2) An advertisement, directed to the general public, indicating that the debt relief agency provides assistance with respect to credit defaults, mortgage foreclosures, eviction proceedings, excessive debt, debt collection pressure, or inability to pay any consumer debt shall—"],[1,"(A) disclose clearly and conspicuously in such advertisement that the assistance may involve bankruptcy relief under this title; and"],[1,"(B) include the following statement: \"We are a debt relief agency. We help people file for bankruptcy relief under the Bankruptcy Code.\" or a substantially similar statement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/528?type=usc&year=mostrecent&link-type=html"},"op":34,"ar":2,"head":"§528. Requirements for debt relief agencies","tname":"Bankruptcy","by":{"0":"64, 64, 6, 23, 6, 5, 63, 68, passim, 5, 27, 63, 64, 66, 67, 68, 5, passim"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","subs":["(b)"],"by":{"0":"30"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"0":"13, 33, 36, 37"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 1692a","url":"https://www.law.cornell.edu/uscode/text/15/1692a","subs":["(6)"],"stext":{"head":"§1692a. Definitions","paras":[[0,"As used in this subchapter—"],[1,"(1) The term \"Bureau\" means the Bureau of Consumer Financial Protection."],[1,"(2) The term \"communication\" means the conveying of information regarding a debt directly or indirectly to any person through any medium."],[1,"(3) The term \"consumer\" means any natural person obligated or allegedly obligated to pay any debt."],[1,"(4) The term \"creditor\" means any person who offers or extends credit creating a debt or to whom a debt is owed, but such term does not include any person to the extent that he receives an assignment or transfer of a debt in default solely for the purpose of facilitating collection of such debt for another."],[1,"(5) The term \"debt\" means any obligation or alleged obligation of a consumer to pay money arising out of a transaction in which the money, property, insurance, or services which are the subject of the transaction are primarily for personal, family, or household purposes, whether or not such obligation has been reduced to judgment."],[1,"(6) The term \"debt collector\" means any person who uses any instrumentality of interstate commerce or the mails in any business the principal purpose of which is the collection of any debts, or who regularly collects or attempts to collect, directly or indirectly, debts owed or due or asserted to be owed or due another. Notwithstanding the exclusion provided by clause (F) of the last sentence of this paragraph, the term includes any creditor who, in the process of collecting his own debts, uses any name other than his own which would indicate that a third person is collecting or attempting to collect such debts. For the purpose of section 1692f(6) of this title, such term also includes any person who uses any instrumentality of interstate commerce or the mails in any business the principal purpose of which is the enforcement of security interests. The term does not include—"],[2,"(A) any officer or employee of a creditor while, in the name of the creditor, collecting debts for such creditor;"],[2,"(B) any person while acting as a debt collector for another person, both of whom are related by common ownership or affiliated by corporate control, if the person acting as a debt collector does so only for persons to whom it is so related or affiliated and if the principal business of such person is not the collection of debts;"],[2,"(C) any officer or employee of the United States or any State to the extent that collecting or attempting to collect any debt is in the performance of his official duties;"],[2,"(D) any person while serving or attempting to serve legal process on any other person in connection with the judicial enforcement of any debt;"],[2,"(E) any nonprofit organization which, at the request of consumers, performs bona fide consumer credit counseling and assists consumers in the liquidation of their debts by receiving payments from such consumers and distributing such amounts to creditors; and"],[2,"(F) any person collecting or attempting to collect any debt owed or due or asserted to be owed or due another to the extent such activity (i) is incidental to a bona fide fiduciary obligation or a bona fide escrow arrangement; (ii) concerns a debt which was originated by such person; (iii) concerns a debt which was not in default at the time it was obtained by such person; or (iv) concerns a debt obtained by such person as a secured party in a commercial credit transaction involving the creditor."],[1,"(7) The term \"location information\" means a consumer's place of abode and his telephone number at such place, or his place of employment."],[1,"(8) The term \"State\" means any State, territory, or possession of the United States, the District of Columbia, the Commonwealth of Puerto Rico, or any political subdivision of any of the foregoing."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692a. Definitions","tname":"Commerce and Trade","by":{"0":"19"}},{"t":"usc","label":"11 U.S.C. § 96","url":"https://www.law.cornell.edu/uscode/text/11/96","subs":["(d)(1928)"],"by":{"0":"32"}},{"t":"usc","label":"15 U.S.C. § 7245","url":"https://www.law.cornell.edu/uscode/text/15/7245","by":{"0":"25"}},{"t":"usc","label":"18 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/18/157","by":{"0":"51"}},{"t":"usc","label":"28 U.S.C. § 1927","url":"https://www.law.cornell.edu/uscode/text/28/1927","by":{"0":"25"}},{"t":"reg","label":"31 C.F.R. § 10.20","url":"https://www.ecfr.gov/current/title-31/section-10.20","by":{"0":"25"}},{"t":"reg","label":"37 C.F.R. § 10.20","url":"https://www.ecfr.gov/current/title-37/section-10.20","by":{"0":"25"}},{"t":"rule","label":"Fed. R. App. P. 46","url":"https://www.law.cornell.edu/rules/frap/rule_46","subs":["(c)"],"by":{"0":"25"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","subs":["(c)"],"by":{"0":"25"}},{"t":"reg","label":"72 Fed. Reg. 7082","url":"https://www.govinfo.gov/link/fr/72/7082","by":{"0":"4"}}]};